      if (!(window.matchMedia && window.matchMedia("(max-width: 760px)").matches)) { home(); return; }
      slot.appendChild(nav);
      root.setAttribute("data-crumbs-bar", "");
      if (slot.scrollWidth > slot.clientWidth + 1) { home(); return; }
