    var stepEls = $$(":scope > [data-step]", stage);
    // A Placeholder has the tabs but no screens yet: its Screens tab shows the planned steps.
    var hasSteps = stepEls.length > 0;
    var ids = stepEls.map(function (n) { return n.getAttribute("data-step"); });
    var links = $$("a[data-goto]", root);
    var guides = $$("[data-panel] [data-step]", root);
    // .seg[data-states] is the toolbar control; .step[data-states] (on every step) lists the step's states.
    var stateRadios = $$(".seg[data-states] input[type=radio]", root);
    var statesBox = $(".seg[data-states]", root);
    var frameRadios = $$("[data-frames] input[type=radio]", root);
    var framesBox = $("[data-frames]", root);
    var prev = $("[data-prev]", root), next = $("[data-next]", root), pos = $("[data-position]", root);
    var toggle = $("[data-toggle-panel]", root);
    var grid = $(".viewer", root) || root;
    var caption = $("[data-frame-caption]", root);
