    var viewAs = $("[data-viewas]", root), viewSel = $("[data-viewer-select]", root), dataView = $("[data-dataview]", root);
    var chip = $("[data-data-chip]", root), chipLabel = chip ? $("[data-data-label]", chip) : null;
