    // toolbar above it, and the item's end is the foot below it, the same place on every kind of item.
    page.classList.add("revstage");
    // The content fits the stage (FR-279): scaled down to fit, to a readable minimum, and only then it scrolls.
    REVIEW.fit = el("div", { class: "revfit", "data-review-keep": "" });
